  KEY `post_id` (`post_id`),
  KEY `meta_key` (`meta_key`(191))
) ENGINE=InnoDB AUTO_INCREMENT=19967 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
