(568,1,'2023-10-30 03:54:42','2023-10-30 03:54:42','<!-- wp:navigation-link {\"className\":\" menu-item menu-item-type-post_type menu-item-object-page menu-item-home\",\"description\":\"\",\"id\":\"331\",\"kind\":\"post-type\",\"label\":\"Inicio\",\"opensInNewTab\":false,\"rel\":null,\"title\":\"\",\"type\":\"page\",\"url\":\"https://wpstack.test/\"} /--><!-- wp:navigation-link {\"className\":\" menu-item menu-item-type-post_type menu-item-object-page current_page_parent\",\"description\":\"\",\"id\":\"342\",\"kind\":\"post-type\",\"label\":\"Blog\",\"opensInNewTab\":false,\"rel\":null,\"title\":\"\",\"type\":\"page\",\"url\":\"https://wpstack.test/blog/\"} /--><!-- wp:navigation-link {\"className\":\" menu-item menu-item-type-post_type menu-item-object-page\",\"description\":\"\",\"id\":\"2\",\"kind\":\"post-type\",\"label\":\"Página de ejemplo\",\"opensInNewTab\":false,\"rel\":null,\"title\":\"\",\"type\":\"page\",\"url\":\"https://wpstack.test/pagina-ejemplo/\"} /--><!-- wp:navigation-link {\"className\":\" menu-item menu-item-type-post_type menu-item-object-page\",\"description\":\"\",\"id\":\"77\",\"kind\":\"post-type\",\"label\":\"Template Image Header\",\"opensInNewTab\":false,\"rel\":null,\"title\":\"\",\"type\":\"page\",\"url\":\"https://wpstack.test/template-image-header/\"} /-->','Menú Principal','','publish','closed','closed','','menu-principal','','','2023-10-30 03:54:42','2023-10-30 03:54:42','',0,'https://wpstack.test/menu-principal/',0,'wp_navigation','',0),
